/* a spur gear outline: centre, root and tip radii, teeth */
const KC_gear=(cx,cy,rr,rt,n,fill,st)=>{let p=[];for(let i=0;i<n;i++){const a=i/n*2*Math.PI,d=Math.PI/n;[[a-d*.5,rr],[a-d*.25,rt],[a+d*.25,rt],[a+d*.5,rr],[a+d*1.5,rr]].forEach(([q,r])=>p.push((cx+r*Math.cos(q)).toFixed(1)+','+(cy+r*Math.sin(q)).toFixed(1)))}return `<polygon points="${p.join(' ')}" fill="${fill}" stroke="${st}" stroke-width="3" stroke-linejoin="round"/>`};
