 const r1=row(0,BLU,KC_keyed(110,Y[0]+63,54,38,24,18),'sunk key','half in shaft, half in hub');
 /* 2 feather key: side view, the key fixed on the shaft, the hub slides */
 const y2=Y[1]+70;const r2=row(1,ORG,`<rect x="30" y="${y2-14}" width="200" height="34" rx="4" fill="${KC_LIGHT}" stroke="${KC_STEEL}" stroke-width="3"/><rect x="44" y="${y2-24}" width="172" height="10" rx="2" fill="${KC_KEY}" stroke="${KC_DARK}" stroke-width="2"/>`+
  `<rect x="96" y="${y2-44}" width="52" height="80" rx="6" fill="${KC_HUB}" stroke="#4C6EF5" stroke-width="3" fill-opacity=".85"/>`+KC_dbl(62,y2-56+4,184,y2-56+4,ORG,3),'feather key','the hub slides along');
 /* 3 saddle key: curved key on a plain shaft, no keyway */
 const y3=Y[2]+72;const r3=row(2,PUR,KC_C(110,y3,52,KC_HUB,'#4C6EF5',3)+KC_C(110,y3,36,KC_LIGHT,KC_STEEL,3)+`<path d="M86,${y3-38} A36,36 0 0 1 134,${y3-38} L134,${y3-48} L86,${y3-48} Z" fill="${KC_KEY}" stroke="${KC_DARK}" stroke-width="2.5"/>`,'saddle key','no keyway: friction only');
 /* 4 Woodruff key: side view, a half disc in a deep seat */
 const y4=Y[3]+60;const r4=row(3,RED,`<rect x="30" y="${y4-10}" width="200" height="50" rx="4" fill="${KC_LIGHT}" stroke="${KC_STEEL}" stroke-width="3"/><path d="M90,${y4-14} L170,${y4-14} A40,40 0 0 1 90,${y4-14} Z" fill="${KC_KEY}" stroke="${KC_DARK}" stroke-width="2.5"/>`+KC_T(130,Y[3]+116,'deep seat',{fs:22,fw:700,a:'middle',fill:RED}),'Woodruff key','suits a tapered end');
