/* trap 1 picture: the key's side face between hub (top) and shaft (bottom); the bearing strip is the full height (wrong) or the hub half (right) */
function KC_keySide(col,ok){
 const sy=170,kx=250,kw=110,kh=150,top=sy-kh/2;
 let s=`<rect x="40" y="30" width="560" height="${sy-30}" fill="${KC_HUB}"/>`+`<rect x="40" y="${sy}" width="560" height="${300-sy}" fill="${KC_LIGHT}"/>`+KC_L(40,sy,kx+kw+24,sy,KC_STEEL,3,'stroke-dasharray="10 6"')+
  KC_T(60,62,'hub',{fs:24,fw:800,fill:'#4C6EF5'})+KC_T(60,288,'shaft',{fs:24,fw:800,fill:KC_GREY})+
  `<rect x="${kx}" y="${top}" width="${kw}" height="${kh}" rx="3" fill="${KC_KEY}" stroke="${KC_DARK}" stroke-width="3"/>`;
 if(ok){s+=`<rect x="${kx+kw}" y="${top}" width="16" height="${kh/2}" fill="${col}"/>`+KC_dbl(kx+kw+40,top,kx+kw+40,sy,col,3)+KC_T(kx+kw+60,top+34,'h/2 = 4.5 mm',{fs:26,fw:800,fill:col})+KC_T(kx+kw+60,top+64,'bears on the hub',{fs:22,fw:700,fill:col})}
 else{s+=`<rect x="${kx+kw}" y="${top}" width="16" height="${kh}" fill="${col}"/>`+KC_dbl(kx+kw+40,top,kx+kw+40,top+kh,col,3)+KC_T(kx+kw+60,sy-6,'h = 9 mm',{fs:26,fw:800,fill:col})+KC_T(kx+kw+60,sy+26,'bears?',{fs:22,fw:700,fill:col})}
 return s+KC_arrow(kx-90,top+30,kx-6,top+30,KC_DARK,4)+KC_T(kx-100,top+38,'F',{fs:28,fw:800,a:'end',fill:KC_DARK})}
/* trap 2 picture: one flange with four bolts; the lever arm is the full pitch diameter (wrong) or the radius (right) */
function KC_arm(col,ok){
 const cx=190,cy=170,rp=110;let s=KC_flange(cx,cy,150,rp,4);
 if(ok){s+=KC_L(cx,cy,cx+rp,cy,col,5)+`<rect x="${cx+rp/2-46}" y="${cy-46}" width="92" height="34" rx="8" fill="#fff"/>`+KC_T(cx+rp/2,cy-20,'R = 75',{fs:24,fw:800,a:'middle',fill:col})+KC_arrow(cx+rp,cy,cx+rp,cy-90,col,5)+
  KC_T(370,110,'arm = radius',{fs:26,fw:800,fill:col})+KC_T(370,150,'R = D₁/2 = 75 mm',{fs:24,fill:col})+KC_T(370,196,'F = 2387 N',{fs:28,fw:800,fill:col})}
 else{s+=KC_L(cx-rp,cy,cx+rp,cy,col,5)+`<rect x="${cx-58}" y="${cy+12}" width="116" height="34" rx="8" fill="#fff"/>`+KC_T(cx,cy+38,'D₁ = 150',{fs:24,fw:800,a:'middle',fill:col})+KC_arrow(cx+rp,cy,cx+rp,cy-90,col,5)+
  KC_T(370,110,'arm = diameter?',{fs:26,fw:800,fill:col})+KC_T(370,150,'arm 150 mm',{fs:24,fill:col})+KC_T(370,196,'F = 1194 N',{fs:28,fw:800,fill:col})}
 return s}

function EXTRA(R,ICON){
 /* hook: a gear keyed on a motor shaft, and the key block itself */
 ICON.kcGear=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${KC_box(0,0,380,170,{fill:'#FFFFFF',st:KC_GREY,sw:3,r:18})}
  ${KC_gear(95,85,62,74,16,KC_HUB,'#4C6EF5')}${KC_C(95,85,28,KC_LIGHT,KC_STEEL,3)}<rect x="88" y="49" width="14" height="14" rx="2" fill="${KC_KEY}" stroke="${KC_DARK}" stroke-width="2"/>
  ${KC_T(196,64,'gear on a',{fs:24,fw:800,fill:BLU})}${KC_T(196,96,'motor shaft',{fs:24,fw:800,fill:BLU})}${KC_T(196,130,'600 rpm',{fs:22,fill:KC_GREY})}</g>`;
 ICON.kcBlock=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${KC_box(0,0,380,170,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  <path d="M40,70 L160,70 L190,48 L70,48 Z" fill="#FFE066" stroke="${KC_DARK}" stroke-width="2.5"/><rect x="40" y="70" width="120" height="60" fill="${KC_KEY}" stroke="${KC_DARK}" stroke-width="2.5"/><path d="M160,70 L190,48 L190,108 L160,130 Z" fill="#E8B923" stroke="${KC_DARK}" stroke-width="2.5"/>
  ${KC_T(100,158,'14 mm',{fs:22,a:'middle',fill:KC_GREY})}${KC_T(214,84,'the key',{fs:26,fw:800,fill:ORG})}${KC_T(214,118,'14 × 9 mm',{fs:22,fill:KC_GREY})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.kcKeyR=(x,y)=>{let s=`<rect x="0" y="0" width="420" height="150" fill="${KC_HUB}"/><rect x="0" y="150" width="420" height="150" fill="${KC_LIGHT}"/>`+KC_L(0,150,420,150,KC_STEEL,3,'stroke-dasharray="10 6"')+
  `<rect x="150" y="60" width="120" height="180" rx="3" fill="${KC_KEY}" stroke="${KC_DARK}" stroke-width="3"/>`+KC_L(130,150,290,150,ORG,6)+
  `<rect x="270" y="60" width="18" height="90" fill="${GRN}"/>`+KC_T(296,100,'h/2',{fs:26,fw:800,fill:GRN})+KC_T(20,138,'shear plane',{fs:22,fw:800,fill:ORG})+KC_T(20,40,'hub',{fs:22,fill:'#4C6EF5'})+KC_T(20,280,'shaft',{fs:22,fill:KC_GREY});
  return `<g transform="translate(${x-210} ${y-150})">${s}</g>`};
 ICON.kcPathR=(x,y)=>{const N=['shaft','key','hub','flange','bolts'];let s='';
  N.forEach((t,i)=>{const cx=i%2?290:110,cy=30+i*64;s+=KC_box(cx-80,cy-24,160,48,{fill:'#FFF4E6',st:ORG,sw:3,r:10})+KC_T(cx,cy+8,t,{fs:24,fw:800,a:'middle',fill:ORG});if(i<4){const nx=(i+1)%2?290:110;s+=KC_arrow(cx+(nx>cx?80:-80),cy,nx+(nx>cx?-80:80),cy+64-24,KC_DARK,3,12)}});
  return `<g transform="translate(${x-200} ${y-150})">${s}</g>`};
 ICON.kcBoltR=(x,y)=>`<g transform="translate(${x-160} ${y-150})">${KC_flange(160,150,150,105,4)}${KC_L(160,150,265,150,GRN,6)}${KC_T(212,136,'R',{fs:28,fw:800,a:'middle',fill:GRN})}${KC_arrow(265,150,265,70,GRN,5)}${KC_T(280,84,'F',{fs:28,fw:800,fill:GRN})}</g>`;
}
